import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';
import { UserList } from './UserList';
import { fetchUsers } from '../services/userApi';

jest.mock('../services/userApi');
const mockedFetchUsers = jest.mocked(fetchUsers);

describe('UserList', () => {
  beforeEach(() => {
    mockedFetchUsers.mockReset();
  });

  it('renderiza estado de carregamento inicialmente', () => {
    mockedFetchUsers.mockResolvedValue(new Promise(() => {})); // Mock pendente
    render(<UserList />);
    expect(screen.getByRole('status')).toHaveTextContent('Carregando usuários...');
  });

  it('renderiza mensagem de erro ao falhar no carregamento', async () => {
    mockedFetchUsers.mockRejectedValue(new Error('Erro ao carregar'));
    render(<UserList />);
    expect(await screen.findByRole('alert')).toHaveTextContent('Falha ao carregar usuários: Erro ao carregar');
  });

  it('renderiza lista de usuários ao carregar com sucesso', async () => {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    mockedFetchUsers.mockResolvedValue(users);
    render(<UserList />);
    const list = await screen.findByRole('list', { name: 'Usuários' });
    expect(list).toBeInTheDocument();
    expect(screen.getByText((content, element) => {
      return element !== null && element.tagName.toLowerCase() === 'li' &&
        element.textContent?.includes('Alice') &&
        element.textContent?.includes('alice@example.com');
    })).toBeInTheDocument();
    expect(screen.getByText((content, element) => {
      return element !== null && element.tagName.toLowerCase() === 'li' &&
        element.textContent?.includes('Bob') &&
        element.textContent?.includes('bob@example.com');
    })).toBeInTheDocument();
  });

  it('renderiza mensagem quando não há usuários cadastrados', async () => {
    mockedFetchUsers.mockResolvedValue([]);
    render(<UserList />);
    expect(await screen.findByText('Nenhum usuário cadastrado.')).toBeInTheDocument();
  });

  it('filtra usuários com base na entrada do usuário', async () => {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    mockedFetchUsers.mockResolvedValue(users);
    render(<UserList />);
    const input = await screen.findByLabelText('Filtrar');
    await userEvent.type(input, 'Alice');
    expect(screen.getByText((content, element) => {
      return element !== null && element.tagName.toLowerCase() === 'li' &&
        element.textContent?.includes('Alice') &&
        element.textContent?.includes('alice@example.com');
    })).toBeInTheDocument();
    expect(screen.queryByText((content, element) => {
      return element !== null && element.tagName.toLowerCase() === 'li' &&
        element.textContent?.includes('Bob') &&
        element.textContent?.includes('bob@example.com');
    })).not.toBeInTheDocument();
  });

  it('renderiza mensagem quando nenhum usuário é encontrado na busca', async () => {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    mockedFetchUsers.mockResolvedValue(users);
